// HasVendor applies the HasEdge predicate on the "vendor" edge.
func HasVendor() predicate.VendorPersonnel {
	return predicate.VendorPersonnel(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, VendorTable, VendorColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasVendorWith applies the HasEdge predicate on the "vendor" edge with a given conditions (other predicates).
func HasVendorWith(preds ...predicate.Vendor) predicate.VendorPersonnel {
	return predicate.VendorPersonnel(func(s *sql.Selector) {
		step := newVendorStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VendorPersonnel) predicate.VendorPersonnel {
	return predicate.VendorPersonnel(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VendorPersonnel) predicate.VendorPersonnel {
	return predicate.VendorPersonnel(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VendorPersonnel) predicate.VendorPersonnel {
	return predicate.VendorPersonnel(sql.NotPredicates(p))
}
